    if (state.pickerMode === 'groups') { sheetTitle.textContent = 'Agregar otro grupo'; sheetSubtitle.textContent = 'Grupos autorizados que aún no aparecen en esta comida.'; const list = document.createElement('div'); list.className = 'group-picker'; additionalGroups().forEach(([code, name]) => { const available = capacity(state.mealIndex, code); const button = document.createElement('button'); button.type = 'button'; button.className = 'picker-row'; button.innerHTML = `<span class="code">${code}</span><span class="picker-copy"><strong>${name}</strong><small>Disponible hoy: ${fmt(available)}</small></span><span>＋</span>`; button.onclick = () => addGroup(code); list.appendChild(button); }); if (!list.children.length) list.innerHTML = '<p class="empty">No quedan otros grupos autorizados para agregar en esta comida.</p>'; sheetContent.appendChild(list); return; }
    const [code, name] = group(state.pickerCode), available = capacity(state.mealIndex, code); sheetTitle.textContent = name; sheetSubtitle.textContent = available ? `${fmt(available)} disponible hoy` : 'No quedan porciones disponibles hoy'; const search = document.createElement('input'); search.type = 'search'; search.placeholder = 'Buscar alimento'; search.value = state.search; search.oninput = () => { state.search = search.value; renderSheet(); }; sheetContent.appendChild(search); const stars = favorites(), query = state.search.trim().toLocaleLowerCase('es-MX'), matches = (foods[code] || []).filter(([food, portion]) => !query || `${food} ${portion}`.toLocaleLowerCase('es-MX').includes(query)), favoriteFoods = matches.filter(([food]) => stars.has(`${code}|${food}`));
    const section = (label, items) => { if (!items.length) return; const heading = document.createElement('p'); heading.className = 'sheet-section-title'; heading.textContent = label; sheetContent.appendChild(heading); const list = document.createElement('div'); list.className = 'food-list'; items.forEach(([food, portion]) => { const row = document.createElement('div'); row.className = 'food-row'; const star = document.createElement('button'); star.type = 'button'; star.className = 'favorite'; star.textContent = stars.has(`${code}|${food}`) ? '★' : '☆'; star.onclick = () => toggleFavorite(code, food); const copy = document.createElement('span'); copy.className = 'food-copy'; copy.innerHTML = `<strong>${food}</strong><small>${portion} = 1 porción</small>`; row.append(star, copy); list.appendChild(row); }); sheetContent.appendChild(list); };
    section('Favoritos', favoriteFoods); section(favoriteFoods.length ? 'Todas las opciones' : 'Opciones', matches.filter(([food]) => !stars.has(`${code}|${food}`))); if (!matches.length) sheetContent.insertAdjacentHTML('beforeend', '<p class="empty">No encontramos ese alimento en esta lista.</p>');
